 const y24=series.find(r=>r.year===2024),y25=series.find(r=>r.year===2025),pctChange=y24&&y25&&y24.value>0?(y25.value/y24.value-1)*100:null;
 el.innerHTML=`<span class="eyebrow">${esc(state.municipio)} / CULTIVO</span><h4>${esc(row.name)}</h4><p class="detail-summary">Evolución histórica del valor registrado entre 2003 y 2025. Cada año sin registro permanece ausente en la gráfica.</p><div class="detail-stat-line"><div><strong>${Number.isFinite(row.value)?`${MX(row.value)} MDP`:'s/r'}</strong><span>VALOR 2025</span></div><div><strong>${PCT(pctChange)}</strong><span>VARIACIÓN 2024–2025</span></div><div><strong>${INT(series.length)}</strong><span>AÑOS REPORTADOS</span></div></div><div id="crop-individual-chart" class="chart"></div><div class="detail-tabs"><span class="detail-tag">Unidad: ${esc(unit)}</span>${byMode[0]?`<span class="detail-tag">Modalidad líder: ${esc(byMode[0].name)}</span>`:''}${byVariety[0]?`<span class="detail-tag">Variedad líder: ${esc(byVariety[0].name)}</span>`:''}</div><div class="report-sublabel">DETALLE DISPONIBLE DEL CIERRE 2025</div><div id="crop-individual-table"></div><p class="fineprint">El desglose por variedad y modalidad es exclusivo de 2025. No permite establecer costos, rentabilidad ni causalidad.</p>`;
